mapper.select:
SELECT td.id,td.title,td.status,td.message_level as messageLevel ,
td.tag,td.description,td.message,td.create_time as createTime,
td.expire_time as expireTime,td.complete_time as completeTime,
td.update_time as updateTime,ta.code AS tagCode
FROM todo AS td INNER JOIN tag AS ta ON td.tag = ta.code


        AND td.id = #{id}


        AND title LIKE CONCAT('%', #{title},'%')


        AND status = #{status}


        AND message_level = #{messageLevel}


        AND message LIKE CONCAT('%', #{message},'%')


        AND tag = #{tagCode}


ORDER BY create_time DESC

    LIMIT #{pageNumber},#{pageSize}

mapper.update:
UPDATE todo


        id  = #{id},


        status  = #{status},


        update_time  = #{updateTime},


        expire_time  = #{expireTime}


        complete_time  = #{completeTime}


WHERE id = #{id}

